solution:
function WordBreak(s: string, wordDict: string[]) -> bool {
  let n = s.length();
  let dp: bool[] = [];
  let i = 0;
  while (i <= n) {
    dp.push(false);
    i += 1;
  }
  dp[0] = true;
  let end = 1;
  while (end <= n) {
    let start = 0;
    while (start < end) {
      if (dp[start]) {
        let word = s.substring(start, end);
        if (wordDict.includes(word)) {
          dp[end] = true;
        }
      }
      start += 1;
    }
    end += 1;
  }
  return dp[n];
}
